SELECT Имена_ОЭС.name AS OES, Имена_областей.NAME AS OBL, Имена_станций.NAME, [Газ по годам].numb1120, [Газ по годам].[2016], [Газ по годам].[2017], [Газ по годам].[2018], [Газ по годам].[2019], [Газ по годам].[2020], [Газ по годам].[2021], Имена_станций.MAIN, Имена_станций.тип, Имена_станций.BE
FROM Имена_областей INNER JOIN (Имена_ОЭС INNER JOIN ([Газ по годам] INNER JOIN Имена_станций ON [Газ по годам].numb1120 = Имена_станций.numb) ON Имена_ОЭС.oes = Имена_станций.OES) ON Имена_областей.OBL = Имена_станций.OBL
WHERE ((([Газ по годам].[2018])=0 Or ([Газ по годам].[2018]) Is Null) AND (([Газ по годам].[2021])>0) AND ((Имена_станций.MAIN) Is Null));
